import{_ as r,o as a,c as e,a5 as s}from"./chunks/framework.BZzouRtU.js";const n="/study/images/graphics/light-and-rendered-images.svg",m=JSON.parse('{"title":"光とレンダリングの基本 — シーンから画像を作る","description":"","frontmatter":{"title":"光とレンダリングの基本 — シーンから画像を作る","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"形、表面、光、カメラから画像を作る流れを説明する。ラスタライゼーション、深度、影、直射光と間接光を、CPU・GPUと画面表示につなげる。","aliases":["レンダリング","rendering","ライティング","lighting","直射光","間接光","陰影","影","深度バッファ","ラスタライゼーション","リアルタイム","オフラインレンダリング"],"verification":"Microsoftの描画パイプライン・深度テスト、Unityの照明・影、KhronosのPBR資料に照合（2026-11-07）"}},"headers":[],"relativePath":"graphics/basics/light-and-rendered-images.md","filePath":"graphics/basics/light-and-rendered-images.md"}'),i={name:"graphics/basics/light-and-rendered-images.md"};function o(g,t,h,d,l,c){return a(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="光とレンダリングの基本-—-シーンから画像を作る" tabindex="-1">光とレンダリングの基本 — シーンから画像を作る <a class="header-anchor" href="#光とレンダリングの基本-—-シーンから画像を作る" aria-label="Permalink to &quot;光とレンダリングの基本 — シーンから画像を作る&quot;">​</a></h1><p>3Dの形や表面の設定を用意しても、そのままではディスプレイの2次元の画像にはなりません。<strong>レンダリング</strong>は、シーンのデータから画像を計算する処理です。何を、どこから、どんな光で見るかを決めて、画面に使う色を求めます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/overviews-direct3d-11-graphics-pipeline" target="_blank" rel="noreferrer">Microsoftの描画パイプライン</a> · <a href="/study/graphics/basics/transforms-and-cameras.html">カメラと座標の基礎</a></p><h2 id="画像を作るための入力" tabindex="-1">画像を作るための入力 <a class="header-anchor" href="#画像を作るための入力" aria-label="Permalink to &quot;画像を作るための入力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入力</th><th>決めること</th></tr></thead><tbody><tr><td><strong>シーン</strong></td><td>物体、カメラ、ライトなどの配置。</td></tr><tr><td><strong>メッシュ</strong></td><td>物体の形と、頂点の位置や表面の向き。</td></tr><tr><td><strong>マテリアル</strong></td><td>色、粗さ、参照するテクスチャなど、表面の計算に使う設定。</td></tr><tr><td><strong>カメラ</strong></td><td>どこから、どちらを向いて、どの範囲を見るか。</td></tr><tr><td><strong>光の情報</strong></td><td>光源の位置や方向、強さ、周囲から届く光など。</td></tr></tbody></table><p>同じ物体でも、ライトやカメラを動かすと見た目が変わります。光と表面の関係から明るさや色を計算する処理を<strong>ライティング</strong>、表面の色などを求める処理を広く<strong>シェーディング</strong>と呼びます。<a href="https://docs.unity3d.com/2022.3/Documentation/Manual/LightingInUnity.html" target="_blank" rel="noreferrer">Unityのライティングの導入</a> · <a href="/study/graphics/basics/materials-textures-and-shaders.html">マテリアルの基礎</a></p><figure class="study-figure"><img src="'+n+'" alt="形・表面・光・カメラのデータをもとに、CPUが描画する仕事を用意し、GPUが画面に覆われる範囲と色・深度を計算する。完成した画像を表示に使う。光源から直接届く光と、別の表面で反射して届く光を区別する。" width="760" height="476" loading="lazy"><figcaption>三角形を画面へ写す描画方式の概念図です。実際には複数の描画パスを組み合わせます。<a href="/study/images/graphics/light-and-rendered-images.svg" target="_blank" rel="noopener noreferrer">光と画像生成の図を拡大</a></figcaption></figure><h2 id="三角形から画面の色へ" tabindex="-1">三角形から画面の色へ <a class="header-anchor" href="#三角形から画面の色へ" aria-label="Permalink to &quot;三角形から画面の色へ&quot;">​</a></h2><p>ゲームでよく使う<strong>ラスタライゼーション</strong>では、三角形などをカメラから見た画面へ写し、どの画素・サンプルを覆うかを調べます。頂点から渡されたUVや向きなどを補間し、シェーダーがテクスチャや光の情報を使って色などを求めます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/d3d10-graphics-programming-guide-rasterizer-stage" target="_blank" rel="noreferrer">Microsoftのラスタライザー</a></p><p>複数の物体が重なる場所では、手前の物体を見せる必要があります。<strong>深度バッファ</strong>は、画面の各位置について奥行きの情報を保持します。一般的な不透明物体の描画では、新しく描く面の深度と保存済みの深度を比較する<strong>深度テスト</strong>で、手前の面を選びます。半透明の面は、色を混ぜる順序なども考えて描きます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/d3d10-graphics-programming-guide-output-merger-stage" target="_blank" rel="noreferrer">Microsoftの深度テストとブレンド</a> · <a href="/study/graphics/pipeline/rasterization.html">ラスタライゼーションの詳細</a></p><h2 id="直接届く光と、反射して届く光" tabindex="-1">直接届く光と、反射して届く光 <a class="header-anchor" href="#直接届く光と、反射して届く光" aria-label="Permalink to &quot;直接届く光と、反射して届く光&quot;">​</a></h2><p><strong>直射光</strong>は、光源から表面へ直接届く光です。<strong>間接光</strong>は、別の表面などで反射してから届く光です。例えば白い箱を赤い壁の近くへ置くと、壁で反射した光が箱の色へ影響する場合があります。このような光の回り込みを含めて扱う仕組みを、**グローバルイルミネーション（GI）**と呼びます。<a href="https://docs.unity3d.com/2022.3/Documentation/Manual/LightingInUnity.html" target="_blank" rel="noreferrer">Unityの照明の考え方</a> · <a href="/study/graphics/lighting/gi.html">GIの詳解</a></p><p>リアルタイムのゲームでは、照明をその場で計算する部分と、前もって計算しておく部分を組み合わせることがあります。例えば、静止した壁に届く光を画像へ保存した<strong>ライトマップ</strong>や、空間の点に記録する<strong>ライトプローブ</strong>を使います。動く物体や光にどう対応するかは、採用した方式で変わります。<a href="https://docs.unity.com/en-us/engine/6000.0/manual/lighting-overview/direct-and-indirect-lighting" target="_blank" rel="noreferrer">Unityの照明データと事前計算</a></p><h2 id="影には、光が遮られるかの計算が必要" tabindex="-1">影には、光が遮られるかの計算が必要 <a class="header-anchor" href="#影には、光が遮られるかの計算が必要" aria-label="Permalink to &quot;影には、光が遮られるかの計算が必要&quot;">​</a></h2><p>物体の向きによって暗くなる<strong>陰影</strong>に加え、別の物体が光を遮ってできる<strong>影</strong>もあります。影を付けるには、ライトから見てどこが遮られるかを調べるなど、影のための処理を用意します。<strong>シャドウマップ</strong>は、光源側から見た深度を使い、表面へ光が届くかを判定する方式です。<a href="https://docs.unity.com/en-us/engine/6000.0/manual/lighting-overview/shadows/shadow-realtime" target="_blank" rel="noreferrer">Unityのリアルタイムシャドウ</a></p><p>影を落とすか・受けるか、対象距離、解像度などの設定は見た目と負荷に影響します。画面にモデルとライトがあっても、影の計算方式と対応する設定を確認します。<a href="https://docs.unity.com/en-us/engine/6000.0/manual/lighting-overview/shadows" target="_blank" rel="noreferrer">Unityの影の設定</a> · <a href="/study/graphics/lighting/shadow.html">シャドウの詳解</a></p><h2 id="リアルタイムとオフライン" tabindex="-1">リアルタイムとオフライン <a class="header-anchor" href="#リアルタイムとオフライン" aria-label="Permalink to &quot;リアルタイムとオフライン&quot;">​</a></h2><p><strong>リアルタイムレンダリング</strong>では、入力や世界の変化に応じて画像を継続的に作り、表示に間に合わせます。<strong>オフラインレンダリング</strong>では、映像や静止画などのために、出力する画像を時間をかけて計算できます。同じ目的でも、許される計算時間に応じて方式や設定を選びます。ゲームでも画像制作でも、光を反射しながら追うパストレーシングを使う構成があります。<a href="/study/graphics/lighting/path-tracing.html">パストレーシング</a> · <a href="/study/graphics/optimization/frame-pacing.html">フレームタイム</a></p><p>**PBR（物理ベースレンダリング）**は、光と表面の関係を物理的なモデルに基づいて扱う考え方です。例えばglTFでは、ベースカラー、金属度、粗さで表面を指定するモデルを使います。光の計算やカメラの露出なども、最終的な見た目に関わります。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#materials" target="_blank" rel="noreferrer">glTFのPBRマテリアル</a> · <a href="/study/graphics/lighting/pbr.html">PBRの詳解</a></p><h2 id="cpuが用意し、gpuが描き、画像を表示する" tabindex="-1">CPUが用意し、GPUが描き、画像を表示する <a class="header-anchor" href="#cpuが用意し、gpuが描き、画像を表示する" aria-label="Permalink to &quot;CPUが用意し、GPUが描き、画像を表示する&quot;">​</a></h2><p>CPU側でゲームの状態を更新し、見える物体や描画に必要な仕事を用意します。GPUへ渡すコマンドで、頂点の変換、色や深度の計算、後処理などを進めます。描画の完了と、ディスプレイがその画像を見せる時点には、それぞれの待ち時間や表示の仕組みが関わります。<a href="/study/graphics/pipeline/overview.html">描画パイプラインの全体像</a> · <a href="/study/graphics/optimization/swap-chain-and-vsync.html">スワップチェーンとVSync</a></p><p>ゲームの更新と描画のつながりは<a href="/study/game/basics/game-loop-and-time.html">ゲームループと時間</a>、形のデータは<a href="/study/graphics/basics/models-and-meshes.html">モデルとメッシュ</a>へ進めます。</p>',21)])])}const u=r(i,[["render",o]]);export{m as __pageData,u as default};
